@Service
public class OrderService {
    private final CustomerRepository customerRepo;
    private PaymentGateway paymentGateway;

    // Constructor injection - preferred for required dependencies
    @Autowired
    public OrderService(CustomerRepository customerRepo) {
        this.customerRepo = customerRepo;
    }

    // Setter injection - used for optional dependencies
    @Autowired
    public void setPaymentGateway(PaymentGateway gateway) {
        this.paymentGateway = gateway;
    }

    public void processOrder(Long customerId, Order order) {
        var customer = customerRepo.findById(customerId);
        paymentGateway.charge(customer, order.getTotal());
    }
}

@Repository
public class CustomerRepository {
