@Service
public class OrderService {
    // Required dependency - app won't start if EmailService bean is missing
    private final EmailService emailService;

    // Optional dependency - injects null if MetricsCollector bean doesn't exist
    @Autowired(required = false)
    private MetricsCollector metricsCollector;

    @Autowired
    public OrderService(EmailService emailService) {
        this.emailService = emailService;
    }

    public void processOrder(Order order) {
        emailService.sendConfirmation(order);
        // Safe null check for optional dependency
        if (metricsCollector != null) {
            metricsCollector.recordOrderProcessed();
        }
    }
}

// If EmailService is not marked @Service, Spring throws:
// NoSuchBeanDefinitionException: No qualifying bean of type 'EmailService'
