@Configuration
public class DataSourceConfig {

    @Bean
    @Primary  // This is the default DataSource for most services
    public DataSource mysqlDataSource() {
        var ds = new HikariDataSource();
        ds.setJdbcUrl("jdbc:mysql://localhost:3306/main");
        return ds;
    }

    @Bean("analyticsDataSource")
    public DataSource postgresDataSource() {
        var ds = new HikariDataSource();
        ds.setJdbcUrl("jdbc:postgresql://localhost:5432/analytics");
        return ds;
    }
}

@Repository
public class OrderRepository {
    private final DataSource dataSource;

    public OrderRepository(DataSource dataSource) {  // Gets mysqlDataSource due to @Primary
        this.dataSource = dataSource;
    }
}

@Repository
public class AnalyticsRepository {
    private final DataSource dataSource;

    public AnalyticsRepository(@Qualifier("analyticsDataSource") DataSource dataSource) {
        this.dataSource = dataSource;  // Explicitly requests Postgres, overrides @Primary
    }
}
