import jakarta.inject.Inject;
import jakarta.inject.Named;
import java.util.Optional;

@Named
class OrderService {
    private final Optional<MetricsCollector> metrics;

    // Standard annotation: works in Spring, Guice or CDI.
    // No required attribute -> model optionality with Optional<T>.
    @Inject
    OrderService(Optional<MetricsCollector> metrics) {
        this.metrics = metrics;
    }
}
```
Inside Spring both behave the same; `@Inject` keeps the class portable across DI containers.

