@Service
public class PaymentService {
    private final List<PaymentHandler> handlers;

    @Autowired
    public PaymentService(List<PaymentHandler> handlers) {
        this.handlers = handlers;  // Spring injects ALL PaymentHandler beans
    }

    public void processPayment(Order order) {
        for (var handler : handlers) {
            if (handler.supports(order.getPaymentType())) {
                handler.process(order);
                return;
            }
        }
        throw new IllegalArgumentException("No handler for " + order.getPaymentType());
    }
}

@Component
class CreditCardHandler implements PaymentHandler {
    public boolean supports(String type) { return "CREDIT_CARD".equals(type); }
    public void process(Order order) { /* Stripe API call */ }
}

@Component
class PayPalHandler implements PaymentHandler {
    public boolean supports(String type) { return "PAYPAL".equals(type); }
    public void process(Order order) { /* PayPal API call */ }
}
